	tests := []struct {
		value string
		want  string
	}{
		{value: "1910-09-01", want: "1910-09-01"},
		{value: " 1910-09-01 ", want: "1910-09-01"},
		{value: "1910-09-31", want: ""},
		{value: "01/09/1910", want: ""},
		{value: "", want: ""},
	}

	for _, tt := range tests {
		if got := normalizeDate(tt.value); got != tt.want {
			t.Fatalf("normalizeDate(%q) = %q, queria %q", tt.value, got, tt.want)
		}
	}
