func TestPrintStats(t *testing.T) {
	var output bytes.Buffer

	printStats(&output, Stats{RecordsRead: 12, MalformedRecords: 3})

	want := "Resultados do Batch\n\nMétrica                           Total\nRegistros lidos                   12\nRegistros Malformados             3\nClubes Filtrados(SEM CAMPEONATO)  0\nClubes Série A                    0\nClubes Série B                    0\nLinhas de Clubes Geradas          0\n"
	if output.String() != want {
		t.Fatalf("saida = %q, queria %q", output.String(), want)
	}
}

package main

import (
	"bufio"
	"encoding/csv"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"text/tabwriter"
	"time"
)

type Stats struct {
	RecordsRead          int64
	MalformedRecords     int64
	FilteredChampionship int64
	SerieAClubs          int64
	SerieBClubs          int64
	ClubRowsWritten      int64
	PlayerRowsWritten    int64
}

type Club struct {
	ClubID       string   `json:"club_id"`
	Name         string   `json:"name"`
	Championship string   `json:"championship"`
	FoundingDate string   `json:"founding_date"`
	City         string   `json:"city"`
	State        string   `json:"state"`
	Country      string   `json:"country"`
	Stadium      string   `json:"stadium"`
	President    string   `json:"president"`
	Nickname     *string  `json:"nickname"`
	Players      []Player `json:"players"`
	Colors       []string `json:"colors"`
}

var clubHeader = []string{
	"Id do Clube",
	"Nome",
	"Campeonato",
	"Data de Fundação",
	"Cidade",
	"Estado",
	"País",
	"Estádio",
	"Presidente",
	"Apelido",
	"Cores",
}

type Player struct {
	PlayerID    string `json:"player_id"`
	Name        string `json:"name"`
	Age         *int   `json:"age"`
	Goals       *int   `json:"goals"`
	DebutDate   string `json:"debut_date"`
	Position    string `json:"position"`
	ShirtNumber *int   `json:"shirt_number"`
}

var playerHeader = []string{
	"Id do Clube",
	"Id do Jogador",
	"Nome",
	"Idade",
	"Gols",
	"Data de Estreia",
	"Posição",
	"Número da Camisa",
}

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

func run(args []string, stdout, stderr io.Writer) int {
	if len(args) != 1 {
		fmt.Fprintln(stderr, "uso: batch <input.jsonl>")
		return 1
	}

	inputPath := args[0]

	if !isJSONL(inputPath) {
		fmt.Fprintln(stderr, "erro: arquivo fora da extensão .jsonl")
		return 1
	}

	inputFile, err := os.Open(inputPath)
	if err != nil {
		fmt.Fprintf(stderr, "erro ao abrir o arquivo de entrada: %v\n", err)
		return 1
	}
	defer inputFile.Close()

	clubsFile, err := os.Create("clubs.csv")
	if err != nil {
		fmt.Fprintf(stderr, "erro ao criar clubs.csv: %v\n", err)
		return 1
	}
	defer clubsFile.Close()

	playersFile, err := os.Create("players.csv")
	if err != nil {
		fmt.Fprintf(stderr, "erro ao criar clubs.csv: %v\n", err)
		return 1
	}
	defer playersFile.Close()

	stats, err := process(inputFile, clubsFile, playersFile)
	if err != nil {
		fmt.Fprintf(stderr, "erro ao processar arquivo: %v\n", err)
		return 1
	}

	printStats(stdout, stats)

	return 0
}

func process(r io.Reader, clubsOutput, playersOutput io.Writer) (Stats, error) {
	reader := bufio.NewReader(r)

	clubsWriter := csv.NewWriter(clubsOutput)
	playersWriter := csv.NewWriter(playersOutput)

	if err := clubsWriter.Write(clubHeader); err != nil {
		return Stats{}, err
	}

	if err := playersWriter.Write(playerHeader); err != nil {
		return Stats{}, err
	}

	var stats Stats

	for {
		line, err := reader.ReadBytes('\n')

		if len(line) > 0 {
			stats.RecordsRead++

			var club Club

			if err := json.Unmarshal(line, &club); err != nil {
				stats.MalformedRecords++
				continue
			} else {
				championship, ok := filterChampionship(club.Championship)
				if !ok {
					stats.FilteredChampionship++
					continue
				}

				switch championship {
				case "SERIE A":
					stats.SerieAClubs++
				case "SERIE B":
					stats.SerieBClubs++
				}

				if err := clubsWriter.Write(clubRow(club)); err != nil {
					return stats, err
				}
				stats.ClubRowsWritten++

				for _, player := range club.Players {
					if err := playersWriter.Write(playerRow(club.ClubID, player)); err != nil {
						return stats, err
					}
					stats.PlayerRowsWritten++
				}
			}
		}

		if errors.Is(err, io.EOF) {
			break
		}

		if err != nil {
			return stats, err
		}
	}

	clubsWriter.Flush()
	if err := clubsWriter.Error(); err != nil {
		return stats, err
	}

	playersWriter.Flush()
	if err := playersWriter.Error(); err != nil {
		return stats, err
	}
	return stats, nil
}

// WRITERS (Later i need to put this into package)
func clubRow(club Club) []string {
	nickname := ""
	if club.Nickname != nil {
		nickname = *club.Nickname
	}

	return []string{
		club.ClubID,
		club.Name,
		club.Championship,
		normalizeDate(club.FoundingDate),
		club.City,
		club.State,
		club.Country,
		club.Stadium,
		club.President,
		nickname,
		strings.Join(club.Colors, "|"),
	}
}

func playerRow(clubID string, player Player) []string {
	return []string{
		clubID,
		player.PlayerID,
		player.Name,
		intValue(player.Age),
		intValue(player.Goals),
		normalizeDate(player.DebutDate),
		player.Position,
		intValue(player.ShirtNumber),
	}
}

// HELPERS
func isJSONL(path string) bool {
	return strings.EqualFold(filepath.Ext(path), ".jsonl")
}

func filterChampionship(value string) (string, bool) {
	championship := strings.TrimSpace(value)

	switch championship {
	case "SERIE A", "SERIE B":
		return championship, true
	default:
		return "", false
	}
}

func intValue(value *int) string {
	if value == nil {
		return ""
	}

	return strconv.Itoa(*value)
}

func normalizeDate(value string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return ""
	}

	t, err := time.Parse("2006-01-02", value)
	if err != nil {
		return ""
	}

	return t.Format("2006-01-02")
}

func printStats(stdout io.Writer, stats Stats) {
	w := tabwriter.NewWriter(stdout, 0, 0, 2, ' ', 0)
	defer w.Flush()

	fmt.Fprintln(w, "Resultados do Batch")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "Métrica\tTotal")
	fmt.Fprintf(w, "Registros lidos\t%d\n", stats.RecordsRead)
	fmt.Fprintf(w, "Registros Malformados\t%d\n", stats.MalformedRecords)
	fmt.Fprintf(w, "Clubes Filtrados(SEM CAMPEONATO)\t%d\n", stats.FilteredChampionship)
	fmt.Fprintf(w, "Clubes Série A\t%d\n", stats.SerieAClubs)
	fmt.Fprintf(w, "Clubes Série B\t%d\n", stats.SerieBClubs)
	fmt.Fprintf(w, "Linhas de Clubes Geradas \t%d\n", stats.ClubRowsWritten)
	fmt.Fprintf(w, "Linhas de Jogadores Geradas \t%d\n", stats.PlayerRowsWritten)
}

