	for _, tt := range []struct {
		name    string
		workers int
		wantErr bool
	}{
		{name: "zero uses sequential processing", workers: 0},
		{name: "one worker", workers: 1},
		{name: "more workers than records", workers: 8},
		{name: "negative worker count", workers: -1, wantErr: true},
	} {
