		{value: "  SERIE A  ", want: "SERIE A", ok: true},
		{value: "SERIE C"},
		{value: ""},
	} {
		got, ok := filterChampionship(tt.value)
		if got != tt.want || ok != tt.ok {
			t.Fatalf("filterChampionship(%q) = (%q, %t), want (%q, %t)", tt.value, got, ok, tt.want, tt.ok)
		}
	}
}

