 func workerTestInput(records int) string {
 	var input strings.Builder

 	for i := 0; i < records; i++ {
 		if i%97 == 0 {
 			input.WriteString("invalid json\n")
 			continue
 		}

 		championship := "SERIE A"
 		switch i % 3 {
 		case 1:
 			championship = "SERIE B"
 		case 2:
 			championship = "SERIE C"
 		}

 		fmt.Fprintf(
