display.text:
package main

import (
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"text/tabwriter"

	"github.com/prettyletto/bigdatacorp-batch-challenge/internal/batch"
)

type atomicOutput struct {
	file        *os.File
	destination string
}

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

func run(args []string, stdout, stderr io.Writer) int {
	flags := flag.NewFlagSet(
		"batch",
		flag.ContinueOnError,
	)

	flags.SetOutput(stderr)

	var (
		workers int
		maxSize int
		verbose bool
	)

	flags.IntVar(
		&workers,
		"workers",
		1,
		"quantidade de workers para processamento",
	)
	flags.IntVar(
		&maxSize,
		"maxsize",
		32,
		"tamanho máximo do batch em MiB",
	)
	flags.BoolVar(
		&verbose,
		"v",
		false,
		"exibe logs de processamento em stderr",
	)

	flags.Usage = func() {
		fmt.Fprintln(stderr, "uso: batch [-v] [-workers N] [-maxsize MiB] <input.jsonl>")
	}

	if err := flags.Parse(args); err != nil {
		return 1
	}

	if flags.NArg() != 1 {
		flags.Usage()
		return 1
	}

	if workers < 1 {
		fmt.Fprintln(stderr, "erro: workers deve ser maior que zero")
		return 1
	}
	if maxSize < 1 {
		fmt.Fprintln(stderr, "erro: maxsize deve ser maior que zero")
		return 1
	}

	inputPath := flags.Arg(0)

	if !isJSONL(inputPath) {
		fmt.Fprintf(stderr, "erro: arquivo fora da extensão .jsonl")
		return 1
	}

	inputFile, err := os.Open(inputPath)
	if err != nil {
		fmt.Fprintf(stderr, "erro ao abrir o arquivo de entrada: %v\n", err)
		return 1
	}
	defer inputFile.Close()

	clubsOutput, err := createAtomicOutput("clubs.csv")
	if err != nil {
		fmt.Fprintf(stderr, "erro ao criar clubs.csv: %v\n", err)
		return 1
	}
	defer clubsOutput.Discard()

	playersOutput, err := createAtomicOutput("players.csv")
	if err != nil {
		fmt.Fprintf(stderr, "erro ao criar players.csv: %v\n", err)
		return 1
	}
	defer playersOutput.Discard()

	var onProgress func(batch.Progress)
	if verbose {
		inputInfo, err := inputFile.Stat()
		if err != nil {
			fmt.Fprintf(stderr, "erro ao obter tamanho do arquivo de entrada: %v\n", err)
			return 1
		}
		onProgress = newProgressLogger(stderr, inputInfo.Size())
	}

	stats, err := batch.ProcessWithOptions(inputFile, clubsOutput.file, playersOutput.file, batch.Options{
		Workers:       workers,
		MaxBatchBytes: maxSize << 20,
		OnProgress:    onProgress,
	})
	if err != nil {
		fmt.Fprintf(stderr, "erro ao processar arquivo: %v\n", err)
		return 1
	}
	if err := clubsOutput.Commit(); err != nil {
		fmt.Fprintf(stderr, "erro ao finalizar clubs.csv: %v\n", err)
		return 1
	}
	if err := playersOutput.Commit(); err != nil {
		fmt.Fprintf(stderr, "erro ao finalizar players.csv: %v\n", err)
		return 1
	}

	printStats(stdout, stats)

	return 0
}

func createAtomicOutput(destination string) (*atomicOutput, error) {
	file, err := os.CreateTemp(
		filepath.Dir(destination),
		"."+filepath.Base(destination)+"-*",
	)
	if err != nil {
		return nil, err
	}

	return &atomicOutput{file: file, destination: destination}, nil
}

func (output *atomicOutput) Commit() error {
	if err := output.file.Close(); err != nil {
		return err
	}

	return os.Rename(output.file.Name(), output.destination)
}

func (output *atomicOutput) Discard() {
	_ = output.file.Close()
	_ = os.Remove(output.file.Name())
}

func newProgressLogger(stderr io.Writer, inputSize int64) func(batch.Progress) {
	w := tabwriter.NewWriter(stderr, 0, 0, 2, ' ', 0)
	var nextRecord int64 = 100_000
	var nextPercent int64 = 10

	return func(progress batch.Progress) {
		if inputSize > 0 && inputSize < 100_000 {
			percent := progress.BytesRead * 100 / inputSize
			if percent >= nextPercent {
				writeProgress(w, progress, fmt.Sprintf("%d registros", progress.RecordsRead))
				nextPercent = (percent/10 + 1) * 10
			}
		} else if progress.RecordsRead >= nextRecord {
			writeProgress(w, progress, fmt.Sprintf("%d registros", progress.RecordsRead))
			nextRecord += 100_000
		}

		_ = w.Flush()
	}
}

func writeProgress(w *tabwriter.Writer, progress batch.Progress, processed string) {
	fmt.Fprintf(
		w,
		"Processamento\t%s\t|\tMalformados\t%d\t|\tIgnorados\t%d\n",
		processed,
		progress.MalformedRecords,
		progress.SkippedClubs,
	)
}

func isJSONL(path string) bool {
	return strings.EqualFold(filepath.Ext(path), ".jsonl")
}

func printStats(stdout io.Writer, stats batch.Stats) {
	w := tabwriter.NewWriter(stdout, 0, 0, 2, ' ', 0)
	defer w.Flush()

	fmt.Fprintln(w, "Resultados do Batch")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "Métrica\tTotal")
	fmt.Fprintf(w, "Registros lidos\t%d\n", stats.RecordsRead)
	fmt.Fprintf(w, "Registros Malformados\t%d\n", stats.MalformedRecords)
	fmt.Fprintf(w, "Clubes ignorados por campeonato\t%d\n", stats.FilteredChampionship)
	fmt.Fprintf(w, "Clubes Série A\t%d\n", stats.SerieAClubs)
	fmt.Fprintf(w, "Clubes Série B\t%d\n", stats.SerieBClubs)
	fmt.Fprintf(w, "Linhas de Clubes Geradas \t%d\n", stats.ClubRowsWritten)
	fmt.Fprintf(w, "Linhas de Jogadores Geradas \t%d\n", stats.PlayerRowsWritten)
}

package main

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/prettyletto/bigdatacorp-batch-challenge/internal/batch"
)

func TestRunWithoutInput(t *testing.T) {
	var stdout bytes.Buffer
	var stderr bytes.Buffer

	code := run(nil, &stdout, &stderr)

	if code == 0 {
		t.Fatal("expected a non-zero exit code")
	}
	if stdout.Len() != 0 {
		t.Fatalf("stdout should be empty, got %q", stdout.String())
	}
	if !strings.Contains(stderr.String(), "uso:") {
		t.Fatalf("expected usage message in stderr, got %q", stderr.String())
	}
}

func TestRunRejectsNonJSONLInput(t *testing.T) {
	var stdout bytes.Buffer
	var stderr bytes.Buffer

	code := run([]string{"clubes.json"}, &stdout, &stderr)

	if code == 0 {
		t.Fatal("expected a non-zero exit code")
	}
	if !strings.Contains(stderr.String(), ".jsonl") {
		t.Fatalf("expected JSONL extension error, got %q", stderr.String())
	}
}

func TestRunRejectsMissingFile(t *testing.T) {
	var stdout bytes.Buffer
	var stderr bytes.Buffer

	code := run([]string{filepath.Join(t.TempDir(), "missing.jsonl")}, &stdout, &stderr)

	if code == 0 {
		t.Fatal("expected a non-zero exit code")
	}
	if !strings.Contains(stderr.String(), "erro ao abrir") {
		t.Fatalf("expected input opening error, got %q", stderr.String())
	}
}

func TestRunGeneratesCSVFilesFromSample(t *testing.T) {
	inputPath, err := filepath.Abs(filepath.Join("..", "..", "sample_clubes.jsonl"))
	if err != nil {
		t.Fatalf("resolving sample path: %v", err)
	}
	workingDirectory, err := os.Getwd()
	if err != nil {
		t.Fatalf("getting working directory: %v", err)
	}
	if err := os.Chdir(t.TempDir()); err != nil {
		t.Fatalf("changing working directory: %v", err)
	}
	t.Cleanup(func() { _ = os.Chdir(workingDirectory) })

	var stdout bytes.Buffer
	var stderr bytes.Buffer
	code := run([]string{"-workers", "2", "-maxsize", "1", inputPath}, &stdout, &stderr)

	if code != 0 {
		t.Fatalf("exit code = %d, stderr = %q", code, stderr.String())
	}
	if stderr.Len() != 0 {
		t.Fatalf("stderr should be empty, got %q", stderr.String())
	}
	for _, filename := range []string{"clubs.csv", "players.csv"} {
		if _, err := os.Stat(filename); err != nil {
			t.Fatalf("expected %s to be generated: %v", filename, err)
		}
	}
	if !strings.Contains(stdout.String(), "Registros lidos") {
		t.Fatalf("expected statistics in stdout, got %q", stdout.String())
	}
}

func TestRunRejectsInvalidMaxSize(t *testing.T) {
	var stdout bytes.Buffer
	var stderr bytes.Buffer

	code := run([]string{"-maxsize", "0", "sample_clubes.jsonl"}, &stdout, &stderr)

	if code == 0 {
		t.Fatal("expected a non-zero exit code")
	}
	if !strings.Contains(stderr.String(), "maxsize") {
		t.Fatalf("expected maxsize error, got %q", stderr.String())
	}
}

func TestRunVerboseLogsProgressAndInvalidRecords(t *testing.T) {
	inputPath := filepath.Join(t.TempDir(), "clubes.jsonl")
	input := strings.Join([]string{
		`{"club_id":"SCCP","championship":"SERIE A"}`,
		`json inválido`,
		`{"club_id":"NAC","championship":"SERIE C"}`,
	}, "\n")
	if err := os.WriteFile(inputPath, []byte(input), 0o600); err != nil {
		t.Fatalf("creating input file: %v", err)
	}

	workingDirectory, err := os.Getwd()
	if err != nil {
		t.Fatalf("getting working directory: %v", err)
	}
	if err := os.Chdir(t.TempDir()); err != nil {
		t.Fatalf("changing working directory: %v", err)
	}
	t.Cleanup(func() { _ = os.Chdir(workingDirectory) })

	var stdout bytes.Buffer
	var stderr bytes.Buffer
	code := run([]string{"-v", "-workers", "2", inputPath}, &stdout, &stderr)

	if code != 0 {
		t.Fatalf("exit code = %d, stderr = %q", code, stderr.String())
	}
	for _, message := range []string{"Processamento", "Malformados", "Ignorados"} {
		if !strings.Contains(stderr.String(), message) {
			t.Fatalf("expected %q in verbose stderr, got %q", message, stderr.String())
		}
	}
	if strings.Contains(stderr.String(), "Linha malformada") || strings.Contains(stderr.String(), "Clube ignorado") {
		t.Fatalf("verbose stderr should contain aggregate logs only, got %q", stderr.String())
	}
}

func TestAtomicOutputCommitReplacesDestination(t *testing.T) {
	destination := filepath.Join(t.TempDir(), "clubs.csv")
	if err := os.WriteFile(destination, []byte("previous"), 0o600); err != nil {
		t.Fatalf("creating destination: %v", err)
	}

	output, err := createAtomicOutput(destination)
	if err != nil {
		t.Fatalf("creating atomic output: %v", err)
	}
	temporaryPath := output.file.Name()
	if _, err := output.file.WriteString("updated"); err != nil {
		t.Fatalf("writing temporary output: %v", err)
	}

	if err := output.Commit(); err != nil {
		t.Fatalf("committing output: %v", err)
	}

	content, err := os.ReadFile(destination)
	if err != nil {
		t.Fatalf("reading destination: %v", err)
	}
	if string(content) != "updated" {
		t.Fatalf("destination content = %q, want %q", content, "updated")
	}
	if _, err := os.Stat(temporaryPath); !os.IsNotExist(err) {
		t.Fatalf("temporary output should not exist after commit, stat error = %v", err)
	}
}

func TestAtomicOutputDiscardPreservesDestination(t *testing.T) {
	destination := filepath.Join(t.TempDir(), "players.csv")
	if err := os.WriteFile(destination, []byte("previous"), 0o600); err != nil {
		t.Fatalf("creating destination: %v", err)
	}

	output, err := createAtomicOutput(destination)
	if err != nil {
		t.Fatalf("creating atomic output: %v", err)
	}
	temporaryPath := output.file.Name()
	if _, err := output.file.WriteString("updated"); err != nil {
		t.Fatalf("writing temporary output: %v", err)
	}

	output.Discard()

	content, err := os.ReadFile(destination)
	if err != nil {
		t.Fatalf("reading destination: %v", err)
	}
	if string(content) != "previous" {
		t.Fatalf("destination content = %q, want %q", content, "previous")
	}
	if _, err := os.Stat(temporaryPath); !os.IsNotExist(err) {
		t.Fatalf("temporary output should not exist after discard, stat error = %v", err)
	}
}

func TestIsJSONL(t *testing.T) {
	for _, tt := range []struct {
		path string
		want bool
	}{
		{path: "clubes.jsonl", want: true},
		{path: "CLUBES.JSONL", want: true},
		{path: "clubes", want: false},
		{path: "clubes.json", want: false},
	} {
		if got := isJSONL(tt.path); got != tt.want {
			t.Fatalf("isJSONL(%q) = %t, want %t", tt.path, got, tt.want)
		}
	}
}

func TestPrintStats(t *testing.T) {
	var output bytes.Buffer

	printStats(&output, batch.Stats{RecordsRead: 12, MalformedRecords: 3})

	want := "Resultados do Batch\n\nMétrica                          Total\nRegistros lidos                  12\nRegistros Malformados            3\nClubes ignorados por campeonato  0\nClubes Série A                   0\nClubes Série B                   0\nLinhas de Clubes Geradas         0\nLinhas de Jogadores Geradas      0\n"
	if output.String() != want {
		t.Fatalf("output = %q, want %q", output.String(), want)
	}
}

